1	const PROCESSING_FEE = 5;
2	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
3	const BLOCK_SIZE = 3;
4	const BLOCK_DISCOUNT_PERCENT = 20;
5	const CURSE_SURCHARGE_PERCENT = 50;
6	const HIGH_ENCHANTMENT_THRESHOLD = 5;
7	const HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;
8	const LOYALTY_YEARS_THRESHOLD = 2;
9	const LOYALTY_DISCOUNT_PERCENT = 20;
10	const FOLLOW_UP_DISCOUNT_PERCENT = 15;
11	const DEDUCTIBLE = 100;
12	const CAP_MULTIPLE = 2;
13	// The CLAIM_ prefix marks the claim-side pair. Both are deliberately distinct
14	// from their premium-side namesakes above: a sword can be enchanted enough to
15	// cost more to insure (threshold 5) without being enchanted enough to pay out
16	// less (threshold 8).
17	const CLAIM_HIGH_ENCHANTMENT_THRESHOLD = 8;
18	const CLAIM_HIGH_ENCHANTMENT_REIMBURSEMENT_PERCENT = 50;
19	
20	const BASE_PREMIUMS = {
21	  sword: 100,
22	  amulet: 60,
23	  staff: 80,
24	  potion: 40,
25	  rune: 25,
26	  moonstone: 25,
27	} as const;
28	
29	// What an item is insured FOR, as opposed to what insuring it costs. The cap on
30	// claims is derived from these, so premium discounts never move it.
31	const INSURANCE_VALUES = {
32	  sword: 1000,
33	  amulet: 600,
34	  staff: 800,
35	  potion: 400,
36	  rune: 250,
37	  moonstone: 250,
38	} as const;
39	
40	// The six priced types are the domain, so they are derived from the premium
41	// table rather than restated: a type nobody prices cannot be insured. The
42	// unknown-type case (broomstick) is still a runtime error the tests will drive.
43	type ItemType = keyof typeof BASE_PREMIUMS;
44	
45	// Components (as opposed to main items) are the only things the block rule
46	// applies to, so the distinction has to be data, not a price coincidence.
47	// Typed as a set of ItemType so a component can never name an unpriced type.
48	const COMPONENT_TYPES = new Set<ItemType>(["rune", "moonstone"]);
49	
50	const PERCENT_WHOLE = 100;
51	
52	// Divides rather than multiplying by a rate: `amount * 1.1` introduces
53	// floating-point error that shifts the spec's round-up in MHPCO's favour.
54	const percentOf = (percent: number, amount: number): number =>
55	  (amount * percent) / PERCENT_WHOLE;
56	
57	// MHPCO rounds every money amount in its own favour: premiums (customer pays)
58	// round up, payouts (MHPCO pays) round down.
59	const roundPremiumInMHPCOsFavour = Math.ceil;
60	
61	export type QuoteResult = { premium: number };
62	
63	export type ClaimResult = { payout: number; remainingCap: number };
64	
65	export type ScenarioResult = QuoteResult | ClaimResult;
66	
67	// `material` is accepted but never read: the dragon-material clause reimburses
68	// in full, which is what every ordinary item already gets, so no code can yet
69	// tell dragon from steel. See `reimbursableAmountFor`. All three are optional so
70	// a bare `{ type: "rune" }` typechecks: a rune has no enchantment to speak of,
71	// rather than an enchantment of zero.
72	type Item = {
73	  type: ItemType;
74	  material?: string;
75	  enchantment?: number;
76	  cursed?: boolean;
77	};
78	
79	type Damage = { itemType: string; amount: number };
80	
81	type Incident = { cause: string; damages: Damage[] };
82	
83	type QuoteStep = { op: "quote"; items: Item[] };
84	
85	type ClaimStep = { op: "claim"; policy: number; incident: Incident };
86	
87	type Step = QuoteStep | ClaimStep;
88	
89	const isQuote = (step: Step): step is QuoteStep => step.op === "quote";
90	
91	type Customer = { yearsWithMHPCO: number };
92	
93	type Scenario = {
94	  customer: Customer;
95	  steps: Step[];
96	};
97	
98	const sum = (amounts: number[]): number =>
99	  amounts.reduce((total, amount) => total + amount, 0);
100	
101	// The scenario asks for something MHPCO cannot price or pay: an unpriced item
102	// type, a negative damage, a claim on an item the policy never covered, a claim
103	// on a step that is not a policy. All four are the customer's input being wrong,
104	// not this code being wrong — which is the distinction the CLI needs. A bare
105	// `Error` reaching the CLI is a defect in here and must not be reported as a
106	// rejected scenario, so the class exists to be caught, not merely to be read.
107	export class InvalidScenarioError extends Error {
108	  constructor(message: string) {
109	    super(message);
110	    this.name = "InvalidScenarioError";
111	  }
112	}
113	
114	// The ItemType union is compile-time only, and scenarios arrive as parsed JSON,
115	// so an unknown type has to be caught here rather than trusted. Without this the
116	// missing table entry would quietly poison the arithmetic with NaN.
117	const basePremiumForItem = (item: Item): number => {
118	  const basePremium = BASE_PREMIUMS[item.type];
119	  if (basePremium === undefined) {
120	    throw new InvalidScenarioError(`MHPCO does not insure items of type ${item.type}`);
121	  }
122	  return basePremium;
123	};
124	
125	const sumBasePremiums = (items: Item[]): number => sum(items.map(basePremiumForItem));
126	
127	// Groups of items that are "alike" — same type. The type is kept alongside the
128	// items because the block rule asks about it; recovering it from items[0] would
129	// make every reader re-derive that a group is non-empty and homogeneous.
130	type AlikeItems = { type: ItemType; items: Item[] };
131	
132	const groupByType = (items: Item[]): AlikeItems[] => {
133	  const groups = new Map<ItemType, Item[]>();
134	  for (const item of items) {
135	    const group = groups.get(item.type) ?? [];
136	    group.push(item);
137	    groups.set(item.type, group);
138	  }
139	  return [...groups].map(([type, groupedItems]) => ({ type, items: groupedItems }));
140	};
141	
142	// A block is a discount on the components' combined base premium, not a flat
143	// price: 3 runes are 75 G less 20 % = 60 G. Derived rather than hardcoded so the
144	// 20 % stays visible as the rule it is.
145	const blockBasePremium = (items: Item[]): number => {
146	  const undiscounted = sumBasePremiums(items);
147	  return undiscounted - percentOf(BLOCK_DISCOUNT_PERCENT, undiscounted);
148	};
149	
150	// Exactly BLOCK_SIZE, not "at least": 4 or 7 runes form no block, so a bigger
151	// pile is never cheaper than the block it contains. Components only — three
152	// swords are three separate insurances, not a discounted building block.
153	const formsABlock = ({ type, items }: AlikeItems): boolean =>
154	  items.length === BLOCK_SIZE && COMPONENT_TYPES.has(type);
155	
156	const basePremiumForGroup = (alikeItems: AlikeItems): number =>
157	  formsABlock(alikeItems)
158	    ? blockBasePremium(alikeItems.items)
159	    : sumBasePremiums(alikeItems.items);
160	
161	// Priced per group of alike items rather than over the whole list, so 3 runes
162	// and 3 moonstones each form their own block.
163	const policyBasePremiumFor = (items: Item[]): number =>
164	  sum(groupByType(items).map(basePremiumForGroup));
165	
166	const percentOfWhen = (applies: boolean, percent: number, amount: number): number =>
167	  applies ? percentOf(percent, amount) : 0;
168	
169	// Each item-specific surcharge is a percentage of the affected item's OWN base
170	// premium, so every rule reads as "this much, when this holds". The terms are
171	// summed rather than chosen between: an item can trigger several at once.
172	//
173	// Deliberately two explicit terms rather than a table of rules. The shared
174	// shape is only the arithmetic tail; the conditions differ in kind (a flag vs.
175	// a threshold over an optional number), and nothing in the remaining spec adds
176	// a third item-specific surcharge to generalise over.
177	const surchargeFor = (item: Item): number => {
178	  const base = basePremiumForItem(item);
179	  return (
180	    percentOfWhen(item.cursed === true, CURSE_SURCHARGE_PERCENT, base) +
181	    percentOfWhen(
182	      (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD,
183	      HIGH_ENCHANTMENT_SURCHARGE_PERCENT,
184	      base,
185	    )
186	  );
187	};
188	
189	// Charged alongside the policy base premium — never folded into it, or the
190	// policy-wide modifiers would compound on top of them.
191	const itemSurchargesFor = (items: Item[]): number => sum(items.map(surchargeFor));
192	
193	// Unlike the item-specific surcharges, these are percentages of the WHOLE
194	// policy's base premium. Each is returned already signed — a surcharge is
195	// positive, a discount negative — so the rule and its direction stay on one
196	// line instead of the sign living in a `+`/`-` further down the sum.
197	const policyModifiersFor = (
198	  policyBasePremium: number,
199	  customer: Customer,
200	  isFollowUpContract: boolean,
201	): number[] => [
202	  // Applies to every quote, follow-ups included: the spec treats each item in a
203	  // quote as newly insured, regardless of how long the customer has been around.
204	  percentOf(FIRST_INSURANCE_SURCHARGE_PERCENT, policyBasePremium),
205	  -percentOfWhen(
206	    customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD,
207	    LOYALTY_DISCOUNT_PERCENT,
208	    policyBasePremium,
209	  ),
210	  -percentOfWhen(isFollowUpContract, FOLLOW_UP_DISCOUNT_PERCENT, policyBasePremium),
211	];
212	
213	// The order of the terms is the order of the spec's rules: what the items are
214	// worth, what they individually cost extra, what the policy as a whole is
215	// adjusted by, and MHPCO's fee on top.
216	const quoteFor = (
217	  items: Item[],
218	  customer: Customer,
219	  isFollowUpContract: boolean,
220	): QuoteResult => {
221	  const policyBasePremium = policyBasePremiumFor(items);
222	  const premium = roundPremiumInMHPCOsFavour(
223	    policyBasePremium +
224	      itemSurchargesFor(items) +
225	      sum(policyModifiersFor(policyBasePremium, customer, isFollowUpContract)) +
226	      PROCESSING_FEE,
227	  );
228	  return { premium };
229	};
230	
231	// A follow-up contract is any quote after the customer's first, so what counts
232	// is how many QUOTES precede this step — not how many steps do. Claim steps sit
233	// in the same list and must not push a later quote into follow-up territory.
234	const isFollowUpContract = (precedingSteps: Step[]): boolean =>
235	  precedingSteps.some(isQuote);
236	
237	const insuranceSumFor = (items: Item[]): number =>
238	  sum(items.map((item) => INSURANCE_VALUES[item.type]));
239	
240	// MHPCO pays, so payouts round down.
241	const roundPayoutInMHPCOsFavour = Math.floor;
242	
243	// How much of a damage the policy reimburses, before the deductible. The
244	// clauses are CHOSEN BETWEEN, not summed — unlike the premium surcharges, where
245	// a cursed AND highly-enchanted sword pays both. Written as a chain of
246	// exceptions over a default so precedence is the reading order: the first
247	// matching clause wins.
248	//
249	// Only one exception is listed. Dragon material is the spec's other clause, but
250	// it reimburses in full, which is already the default — so it is deliberately
251	// absent rather than written as a branch returning `damage.amount` unchanged.
252	// A conditional whose arms agree hides that agreement instead of stating it,
253	// and suggests the material is doing work here when it is not. It earns a
254	// branch on the day a test makes dragon differ from ordinary steel.
255	const reimbursableAmountFor = (damage: Damage, damagedItem: Item): number => {
256	  // Negative damage would have MHPCO billing the customer for being attacked.
257	  // Zero is allowed: a scratch below the deductible is a real, if futile, claim.
258	  if (damage.amount < 0) {
259	    throw new InvalidScenarioError(
260	      `Claim reports a damage of ${damage.amount} G, which cannot be negative`,
261	    );
262	  }
263	  return (damagedItem.enchantment ?? 0) >= CLAIM_HIGH_ENCHANTMENT_THRESHOLD
264	    ? percentOf(CLAIM_HIGH_ENCHANTMENT_REIMBURSEMENT_PERCENT, damage.amount)
265	    : damage.amount;
266	};
267	
268	// A damage entry together with the insured item it was matched to. Pairing them
269	// in one value keeps the two from being re-joined by position further down,
270	// where the correctness of the join would rest on an unstated shared ordering.
271	type DamagedItem = { damage: Damage; item: Item };
272	
273	// Each damage entry carries its own deductible: one dragon attack damaging two
274	// items is two damages, and MHPCO withholds 100 G from each. The reimbursement
275	// clauses apply to the damage amount FIRST, so the deductible bites last.
276	const payoutForDamage = ({ damage, item }: DamagedItem): number =>
277	  reimbursableAmountFor(damage, item) - DEDUCTIBLE;
278	
279	// Splits the insured items into the first one of the wanted type and the rest.
280	// A damage with nothing left to match is a claim on something MHPCO never
281	// insured, which voids the whole claim.
282	const claimOneItemOfType = (
283	  itemType: string,
284	  unclaimed: Item[],
285	): { item: Item; stillUnclaimed: Item[] } => {
286	  const index = unclaimed.findIndex((insured) => insured.type === itemType);
287	  if (index === -1) {
288	    throw new InvalidScenarioError(
289	      `Claim damages a ${itemType} beyond what this policy covers`,
290	    );
291	  }
292	  return {
293	    item: unclaimed[index],
294	    stillUnclaimed: unclaimed.filter((_, position) => position !== index),
295	  };
296	};
297	
298	// Pairs each damage entry with the insured item it refers to. An item can only
299	// be damaged once per incident, so entries CONSUME the items they match: two
300	// sword damages need two insured swords. The fold carries the not-yet-matched
301	// items from one entry to the next, which is what makes the consumption a
302	// property of the traversal rather than a side effect on a scratch array.
303	const damagedItemsFor = (damages: Damage[], insuredItems: Item[]): DamagedItem[] =>
304	  damages.reduce<{ damagedItems: DamagedItem[]; unclaimed: Item[] }>(
305	    ({ damagedItems, unclaimed }, damage) => {
306	      const { item, stillUnclaimed } = claimOneItemOfType(damage.itemType, unclaimed);
307	      return {
308	        damagedItems: [...damagedItems, { damage, item }],
309	        unclaimed: stillUnclaimed,
310	      };
311	    },
312	    { damagedItems: [], unclaimed: insuredItems },
313	  ).damagedItems;
314	
315	// The cap is a property of the POLICY, not of the claim: twice what the policy's
316	// items are insured for. Kept separate from the payout so the cross-claim
317	// accumulation the spec still demands has an obvious place to attach.
318	const capFor = (policy: QuoteStep): number =>
319	  insuranceSumFor(policy.items) * CAP_MULTIPLE;
320	
321	// The cap is spent down across every claim on a policy rather than reset per
322	// claim, so the caller supplies what is left; a claim wanting more than remains
323	// is cut short by it.
324	const claimFor = (claim: ClaimStep, policy: QuoteStep, capRemaining: number): ClaimResult => {
325	  const damagedItems = damagedItemsFor(claim.incident.damages, policy.items);
326	  const payoutBeforeCap = roundPayoutInMHPCOsFavour(
327	    sum(damagedItems.map(payoutForDamage)),
328	  );
329	  const payout = Math.min(payoutBeforeCap, capRemaining);
330	  return { payout, remainingCap: capRemaining - payout };
331	};
332	
333	// `claim.policy` indexes the scenario's steps, and the referenced step must be a
334	// quote — a claim against a claim is meaningless. Nothing validates the scenario
335	// yet, so this states the assumption instead of casting past it; the
336	// error-case tests will turn the throw into a reported error.
337	const policyReferencedBy = (claim: ClaimStep, steps: Step[]): QuoteStep => {
338	  const step = steps[claim.policy];
339	  if (step === undefined || !isQuote(step)) {
340	    throw new InvalidScenarioError(
341	      `Claim references step ${claim.policy}, which is not a quote`,
342	    );
343	  }
344	  return step;
345	};
346	
347	// What a policy has left to pay out, keyed by the step index that quoted it.
348	// A policy absent from the map has had no claims yet, so its remaining cap is
349	// still the full `capFor` — the map records spending, not entitlement.
350	type CapRemainingByPolicy = ReadonlyMap<number, number>;
351	
352	// Everything the scenario carries FORWARD from one step to the next. Results
353	// accumulate; caps are spent down. Naming it makes the fold below a transition
354	// between two of these rather than bookkeeping over loose variables.
355	type ScenarioProgress = {
356	  results: ScenarioResult[];
357	  capRemainingByPolicy: CapRemainingByPolicy;
358	};
359	
360	const withCapRemaining = (
361	  capRemainingByPolicy: CapRemainingByPolicy,
362	  policyIndex: number,
363	  capRemaining: number,
364	): CapRemainingByPolicy =>
365	  new Map(capRemainingByPolicy).set(policyIndex, capRemaining);
366	
367	// A claim reads the cap its policy has left and hands back what remains, so it
368	// is the only step kind that advances more than the results list.
369	const claimStepResult = (
370	  step: ClaimStep,
371	  steps: Step[],
372	  capRemainingByPolicy: CapRemainingByPolicy,
373	): { result: ClaimResult; capRemainingByPolicy: CapRemainingByPolicy } => {
374	  const policy = policyReferencedBy(step, steps);
375	  const capRemaining = capRemainingByPolicy.get(step.policy) ?? capFor(policy);
376	  const result = claimFor(step, policy, capRemaining);
377	  return {
378	    result,
379	    capRemainingByPolicy: withCapRemaining(
380	      capRemainingByPolicy,
381	      step.policy,
382	      result.remainingCap,
383	    ),
384	  };
385	};
386	
387	// A quote depends only on the steps BEFORE it (to spot a follow-up contract),
388	// never on what later steps do, so it leaves the caps untouched.
389	const quoteStepResult = (
390	  step: QuoteStep,
391	  precedingSteps: Step[],
392	  customer: Customer,
393	): QuoteResult => quoteFor(step.items, customer, isFollowUpContract(precedingSteps));
394	
395	// A fold rather than a map: claims spend a shared cap, so a step's result
396	// depends on the steps before it. `reduce` says that in the signature — `map`
397	// would promise each step is independent and then quietly break the promise.
398	export const runScenario = (scenario: Scenario): { results: ScenarioResult[] } => {
399	  const { results } = scenario.steps.reduce<ScenarioProgress>(
400	    (progress, step, stepIndex) => {
401	      if (isQuote(step)) {
402	        const result = quoteStepResult(
403	          step,
404	          scenario.steps.slice(0, stepIndex),
405	          scenario.customer,
406	        );
407	        return { ...progress, results: [...progress.results, result] };
408	      }
409	      const { result, capRemainingByPolicy } = claimStepResult(
410	        step,
411	        scenario.steps,
412	        progress.capRemainingByPolicy,
413	      );
414	      return { results: [...progress.results, result], capRemainingByPolicy };
415	    },
416	    { results: [], capRemainingByPolicy: new Map() },
417	  );
418	  return { results };
419	};
