1	import { InvalidScenarioError, runScenario } from "./claim-office.js";
2	
3	const REJECTED_EXIT_CODE = 1;
4	
5	const readStdin = async (): Promise<string> => {
6	  const chunks: string[] = [];
7	  process.stdin.setEncoding("utf8");
8	  for await (const chunk of process.stdin) {
9	    chunks.push(chunk as string);
10	  }
11	  return chunks.join("");
12	};
13	
14	// Only a rejected scenario is reported as a description and an exit code — the
15	// customer sent something MHPCO cannot price. Anything else is a fault in here,
16	// and is left to crash loudly rather than be dressed up as bad input.
17	const main = async (): Promise<void> => {
18	  const scenario = JSON.parse(await readStdin());
19	  try {
20	    process.stdout.write(JSON.stringify(runScenario(scenario)));
21	  } catch (error) {
22	    if (!(error instanceof InvalidScenarioError)) {
23	      throw error;
24	    }
25	    process.stderr.write(`${error.message}\n`);
26	    process.exitCode = REJECTED_EXIT_CODE;
27	  }
28	};
29	
30	await main();
